(r, big) => {
  const n = big ? 64 : r.pick([1, 2, 4, 4, 8]);
  const g = Array.from({ length: n }, () => new Array(n).fill(0));
  // paint random squares so uniform blocks of several sizes appear
  const fill = (top, left, size) => {
    if (size === 1 || r.bool(0.35)) { const v = r.int(0, 1); for (let i = 0; i < size; i++) for (let j = 0; j < size; j++) g[top + i][left + j] = v; return; }
    const h = size / 2;
    fill(top, left, h); fill(top, left + h, h); fill(top + h, left, h); fill(top + h, left + h, h);
  };
  fill(0, 0, n);
  return [g];
}

