function quadCompress(grid: number[][]): any {
  const build = (top: number, left: number, size: number): any => {
    const v = grid[top][left];
    let same = true;
    for (let i = top; i < top + size && same; i++)
      for (let j = left; j < left + size; j++)
        if (grid[i][j] !== v) { same = false; break; }
    if (same) return v;
    const h = size / 2;
    return [build(top, left, h), build(top, left + h, h), build(top + h, left, h), build(top + h, left + h, h)];
  };
  return build(0, 0, grid.length);
}

