class Solution:
    def quadCompress(self, grid: List[List[int]]):
        def build(top, left, size):
            v = grid[top][left]
            if all(grid[i][j] == v for i in range(top, top + size) for j in range(left, left + size)):
                return v
            h = size // 2
            return [build(top, left, h), build(top, left + h, h),
                    build(top + h, left, h), build(top + h, left + h, h)]

        return build(0, 0, len(grid))

