function quadCompress(grid: number[][]): any {
  const build = (top: number, left: number, size: number): any => {
    if (size === 1) return grid[top][left];
    const h = size / 2;
    const kids = [build(top, left, h), build(top, left + h, h), build(top + h, left, h), build(top + h, left + h, h)];
    const allLeaves = kids.every(k => typeof k === "number");
    if (allLeaves && kids.every(k => k === kids[0])) return kids[0];
    return kids;
  };
  return build(0, 0, grid.length);
}

